auth.probe_js:
// Threads is Meta web infrastructure: every page embeds a CurrentUserInitialData blob inside its
// data-sjs script payloads, and it states the answer literally — ACCOUNT_ID and USER_ID are the
// STRING "0" when signed out, a real numeric id plus a NAME when signed in.
// VERIFIED on a signed-out https://www.threads.com/ document (2026-09-12):
//   ["CurrentUserInitialData",[],{"ACCOUNT_ID":"0","USER_ID":"0","NAME":"", ...}]
// The session cookie (sessionid) is HttpOnly and invisible to document.cookie; ds_user_id is the
// readable half of the same session (same pattern as instagram.com) and is used here ONLY as
// corroboration, never as the gate.
let uid = '', name = '';
try {
  const nodes = document.querySelectorAll('script[data-sjs], script[type="application/json"], script:not([src])');
  for (const n of nodes) {
    const t = n.textContent || '';
    const i = t.indexOf('CurrentUserInitialData');
    if (i === -1) continue;
    const seg = t.slice(i, i + 2000);
    const u = seg.match(/"USER_ID"\s*:\s*"(\d+)"/);
    if (!u) continue;
    const nm = seg.match(/"NAME"\s*:\s*"([^"]*)"/);
    uid = u[1];
    if (nm && nm[1]) name = nm[1];
    if (uid !== '0') break;
  }
} catch (e) { return {signed_in:false, why:'could not read CurrentUserInitialData: ' + e.message}; }
let ck = '';
try { ck = document.cookie; } catch (e) { ck = ''; }
const ds = (ck.match(/\bds_user_id=(\d+)/) || [])[1] || '';
if (uid && uid !== '0') return {signed_in:true, as: name || ('threadsid:' + uid), why: ds ? 'CurrentUserInitialData USER_ID + ds_user_id cookie' : 'CurrentUserInitialData USER_ID'};
if (ds) return {signed_in:true, as:'igid:' + ds, why:'USER_ID is 0 in this document but a ds_user_id cookie is present — probably a cached/logged-out shell; re-probe on https://www.threads.com/ before believing either'};
if (!uid) return {signed_in:false, why:'no CurrentUserInitialData blob in this document — wrong origin, or the page never finished serving'};
return {signed_in:false, why:'CurrentUserInitialData USER_ID is "0"'};
